bool credentialsConfigured() {
  return strcmp(WATCH_WIFI_SSID, "YOUR_WIFI_NAME") != 0 &&
         strlen(WATCH_WIFI_SSID) > 0 &&
         strcmp(WATCH_WIFI_PASSWORD, "YOUR_WIFI_PASSWORD") != 0;
}

void drawCentered(const char *text, int16_t y, uint8_t size, uint16_t color,
                  bool opaque = false) {
  if (!displayReady || displaySleeping) return;
  const int16_t width = static_cast<int16_t>(strlen(text) * 6 * size);
  const int16_t centeredX = (BoardPins::LCD_WIDTH - width) / 2;
  display->setFont();
  display->setTextSize(size);
  if (opaque) {
    display->setTextColor(color, RGB565_BLACK);
  } else {
    display->setTextColor(color);
  }
  display->setCursor(centeredX > 0 ? centeredX : 0, y);
  display->print(text);
}

void drawCenteredWithFont(const char *text, int16_t x, int16_t y,
                          int16_t width, int16_t height,
                          const GFXfont *font, uint16_t foreground,
                          uint16_t background, uint8_t fixedAdvance = 0,
                          int16_t leftPadding = -1,
                          int16_t bottomPadding = -1,
                          int16_t horizontalOffset = 0,
                          int16_t rightPadding = -1) {
  if (!displayReady || displaySleeping) return;

  const uint16_t first = pgm_read_word(&font->first);
  const uint16_t last = pgm_read_word(&font->last);
  int16_t penX = 0;
  int16_t minX = INT16_MAX;
  int16_t minY = INT16_MAX;
  int16_t maxX = INT16_MIN;
  int16_t maxY = INT16_MIN;

  for (const char *p = text; *p; ++p) {
    const uint8_t c = static_cast<uint8_t>(*p);
    if (c < first || c > last) continue;
    const GFXglyph *glyph = pgm_read_glyph_ptr(font, c - first);
    const uint8_t glyphWidth = pgm_read_byte(&glyph->width);
    const uint8_t glyphHeight = pgm_read_byte(&glyph->height);
    const int8_t xOffset = pgm_read_sbyte(&glyph->xOffset);
    const int8_t yOffset = pgm_read_sbyte(&glyph->yOffset);
    if (glyphWidth && glyphHeight) {
      const int16_t glyphMinX = penX + xOffset;
      const int16_t glyphMinY = yOffset;
      const int16_t glyphMaxX = glyphMinX + glyphWidth - 1;
      const int16_t glyphMaxY = glyphMinY + glyphHeight - 1;
      if (glyphMinX < minX) minX = glyphMinX;
      if (glyphMinY < minY) minY = glyphMinY;
      if (glyphMaxX > maxX) maxX = glyphMaxX;
      if (glyphMaxY > maxY) maxY = glyphMaxY;
    }
    penX += fixedAdvance ? fixedAdvance : pgm_read_byte(&glyph->xAdvance);
  }

  if (minX == INT16_MAX) {
    display->fillRect(x, y, width, height, background);
    return;
  }
  const int16_t textWidth = maxX - minX + 1;
  const int16_t textHeight = maxY - minY + 1;
  const int16_t cursorX = (leftPadding >= 0
      ? x + leftPadding - minX
      : rightPadding >= 0
          ? x + width - rightPadding - 1 - maxX
          : x + (width - textWidth) / 2 - minX) + horizontalOffset;
  const int16_t cursorY = bottomPadding >= 0
      ? y + height - bottomPadding - textHeight - minY
      : y + (height - textHeight) / 2 - minY;
  const uint8_t *bitmap = pgm_read_bitmap_ptr(font);

  const size_t pixelCount = static_cast<size_t>(width) * height;
  uint16_t *panel = static_cast<uint16_t *>(heap_caps_malloc(
      pixelCount * sizeof(uint16_t), MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
  if (!panel) {
    panel = static_cast<uint16_t *>(
        heap_caps_malloc(pixelCount * sizeof(uint16_t), MALLOC_CAP_8BIT));
  }
  if (!panel) {
    display->fillRect(x, y, width, height, background);
    Serial.printf("FONT: unable to allocate %u-byte panel buffer.\n",
                  static_cast<unsigned>(pixelCount * sizeof(uint16_t)));
    return;
  }
  for (size_t i = 0; i < pixelCount; ++i) panel[i] = background;

  penX = cursorX;
  for (const char *p = text; *p; ++p) {
    const uint8_t c = static_cast<uint8_t>(*p);
    if (c < first || c > last) continue;
    const GFXglyph *glyph = pgm_read_glyph_ptr(font, c - first);
    const uint16_t bitmapOffset = pgm_read_word(&glyph->bitmapOffset);
    const uint8_t glyphWidth = pgm_read_byte(&glyph->width);
    const uint8_t glyphHeight = pgm_read_byte(&glyph->height);
    const int8_t xOffset = pgm_read_sbyte(&glyph->xOffset);
    const int8_t yOffset = pgm_read_sbyte(&glyph->yOffset);

    for (uint8_t row = 0; row < glyphHeight; ++row) {
      for (uint8_t column = 0; column < glyphWidth; ++column) {
        const uint32_t bitIndex =
            static_cast<uint32_t>(row) * glyphWidth + column;
        const uint8_t packed =
            pgm_read_byte(bitmap + bitmapOffset + (bitIndex >> 3));
        if (!(packed & (0x80 >> (bitIndex & 7)))) continue;

        const int16_t panelX = penX + xOffset + column - x;
        const int16_t panelY = cursorY + yOffset + row - y;
        if (panelX >= 0 && panelX < width && panelY >= 0 && panelY < height) {
          panel[static_cast<size_t>(panelY) * width + panelX] = foreground;
        }
      }
    }
    penX += fixedAdvance ? fixedAdvance : pgm_read_byte(&glyph->xAdvance);
  }

  display->draw16bitRGBBitmap(x, y, panel, width, height);
  free(panel);
}

